
# Radial model of the "real" (fabricated) Gomboc.
#
# The genuine mono-monostatic Gomboc has no single closed-form
# equation: as its makers describe (gomboc.eu), it is a "tennis-ball"
# assembly of segments of simple surfaces (cylinder, ellipsoid, cone)
# and planes.  (The Domokos-Varkonyi 2006 proof and the Sloan analytic
# gombocs are DIFFERENT, essentially spherical bodies.)  To reproduce
# the RECOGNISABLE fabricated shape faithfully, its convex star-shaped
# boundary was digitised from a reference model as the radial function
# R(phi, theta) about the centre of mass, sampled on a regular grid of
# GOMBOC_GRID_NPHI colatitude rows (phi = 0..pi inclusive) by
# GOMBOC_GRID_NTH azimuth columns (theta = 0..2pi, wrapping).  The
# generator bilinearly interpolates it.  A spherical-harmonic fit was
# tried first but rings (bumpy under smooth shading) near the beak;
# the direct radial grid is ring-free.  Values are normalised to a
# mean radius of 1 and stored row-major (phi outer, theta inner).
#
# Reference shape: the fabricated Gomboc (Domokos & Varkonyi;
# gomboc.eu). See also Wolfram MathWorld, "Gomboc".

GOMBOC_GRID_NPHI = 97
GOMBOC_GRID_NTH = 192

